INSERT INTO `store_product` (`id`, `name`, `price`, `digital`, `image`, `imageUploadURL`, `updatedBy`, `description`, `instock`, `isHotSaled`, `brand`, `categories`, `model`) VALUES
(1,	'Apple AirPods (2nd Generation)',	199.00,	0,	'',	'https://m.media-amazon.com/images/I/417OJaY3DAL._AC_SL1000_.jpg',	'superadmin',	'HIGH-QUALITY SOUND — Powered by the Apple H1 headphone chip, AirPods (2nd generation) deliver rich, vivid sound.\r\nEFFORTLESS SETUP — After a simple one-tap setup, AirPods are automatically on and always connected. They sense when they’re in your ears and pause when you take them out. And sound seamlessly switches between your iPhone, Apple Watch, Mac, iPad, and Apple TV.\r\nVOICE CONTROL WITH SIRI — Just say “Hey Siri” for assistance without having to reach for your iPhone.\r\n24-HOUR BATTERY LIFE — More than 24 hours total listening time with the Charging Case.\r\nAUDIO SHARING — Easily share audio between two sets of AirPods on your iPhone, iPad, iPod touch, or Apple TV.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See “Additional information” to learn more.',	1,	0,	'Apple',	'Headphones',	'AirPods'),
(2,	'Apple AirPods Pro (2nd Generation)',	239.04,	0,	'',	'https://m.media-amazon.com/images/I/61SUj2aKoEL._AC_SX679_.jpg',	'superadmin',	'RICHER AUDIO EXPERIENCE — The Apple-designed H2 chip helps to create more intelligent noise cancellation and deeply immersive sound. The low-distortion, custom-built driver delivers crisp, clear high notes and full, rich bass in stunning definition.\r\nNEXT-LEVEL ACTIVE NOISE CANCELLATION — Up to 2x more Active Noise Cancellation for dramatically less noise when you want to focus. Transparency mode lets you hear the world around you, and Adaptive Audio seamlessly blends Active Noise Cancellation and Transparency mode for the best listening experience in any environment.\r\nCUSTOMIZABLE FIT — Includes four pairs of silicone tips (XS, S, M, L) to fit a wide range of ears and provide all-day comfort. The tips create an acoustic seal to help keep out noise and secure AirPods Pro in place.\r\nDUST, SWEAT, AND WATER RESISTANT — Both AirPods Pro and the MagSafe Charging Case are IP54 dust, sweat, and water resistant, so you can listen comfortably in more conditions.\r\nPERSONALIZED SPATIAL AUDIO — With sound that suits your unique ear shape along with dynamic head tracking, AirPods Pro deliver an immersive listening experience that places sound all around you. You can also listen to select songs, shows, and movies in Dolby Atmos.\r\nA HIGHER LEVEL OF CONTROL — Manage playback functions from the stem with touch control. Swipe up or down to adjust volume, press to play and pause music or mute and unmute yourself on calls, and press twice to end calls. And hold the stem to switch between listening modes.\r\nLONG BATTERY LIFE — Get up to 6 hours of listening time with Active Noise Cancellation enabled. And get up to 30 hours of total listening time with Active Noise Cancellation enabled, using the case.\r\nA MORE CAPABLE CASE — Keep track of AirPods Pro with Precision Finding and a built-in speaker. A lanyard loop helps keep your AirPods Pro close. Charge with an Apple Watch or MagSafe charger, USB-C charge cable, or Qi-certified charger.\r\nMAGICAL EXPERIENCE — Conversation Awareness intelligently switches AirPods Pro into Transparency mode and lowers your media volume — so it’s easier to interact with people nearby when you choose to. Summon Siri with a simple “Hey Siri” or just “Siri.” AirPods Pro connect to your devices in a tap, pause music when you take them out, and seamlessly switch to the device you’re using. You can even share a song or show between two sets of AirPods.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See “Additional information” to learn more.',	1,	0,	'Apple',	'Headphones',	'AirPods Pro'),
(3,	'Apple Watch Ultra 2 [GPS + Cellular 49mm]',	827.80,	0,	'',	'https://m.media-amazon.com/images/I/71l2pSLyWRL._AC_SL1500_.jpg',	'superadmin',	'CARBON NEUTRAL — Apple Watch Ultra 2 paired with the latest Alpine Loop or Trail Loop is carbon neutral. Learn more about Apple’s commitment to the environment at apple.com/2030.\r\nWHY APPLE WATCH ULTRA 2 — Rugged, capable, and built to meet the demands of endurance athletes, outdoor adventurers, and water sport enthusiasts — with a specialized band for each. The S9 SiP enables a superbright display and a magical new way to quickly and easily interact with your Apple Watch without touching the display. Up to 36 hours of battery life and 72 hours in Low Power Mode.\r\nEXTREMELY RUGGED, INCREDIBLY CAPABLE — 49mm corrosion-resistant titanium case. Large Digital Crown and Customizable Action button for instant control over a variety of functions. 100m water resistance.\r\nBIGGEST, BRIGHTEST DISPLAY YET — Apple’s brightest Always-On Retina display is easy to see, even in direct sunlight. More room for adding complications to customize your watch face and enough space to view six metrics at once.\r\nTHE FREEDOM OF CELLULAR — Cellular is built in. You can call and text without your iPhone, even overseas with international roaming. Stream your favorite music and podcasts. Get directions with Maps.\r\nFOR ATHLETES — Advanced metrics and views in the Workout app, including Heart Rate Zones, custom workouts, and new cycling workout views. Precision dual-frequency GPS provides incredible accuracy for calculating distance, pace, and route maps. Trail Loop is a light, thin, and flexible band, designed especially for all workout types.\r\nFOR OUTDOOR ADVENTURERS — The Compass app delivers helpful views and details like elevation, incline, longitude, and latitude. See the last place where you had cellular reception. Mark your location with Compass Waypoints. Backtrack uses GPS to map where you’ve been so you can retrace your steps. Alpine Loop is an extremely rugged and secure band to meet the needs of all outdoor adventurers.\r\nFOR WATER SPORTS ENTHUSIASTS — Made for recreational water sports, scuba, and free diving for descents to 40 meters. The Depth app shows the time, current depth, water temperature, duration under water, and maximum depth you’ve reached. The Oceanic+ app puts a dive computer on your wrist. Ocean Band is light and flexible, with a titanium buckle and adjustable loop for a secure fit even during high-speed water sports.\r\nADVANCED HEALTH AND SAFETY FEATURES — Heart health notifications and the ECG app keep you informed and empowered when it comes to your health. Fall Detection and Crash Detection can connect you with emergency services in the event of a hard fall or a severe car crash. Hold the Action button to activate a siren that can be heard up to 600 feet away.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See below to learn more.',	1,	0,	'Apple',	'Watch',	'Apple Watch Ultra 2'),
(4,	'Apple Watch SE (2nd Gen) [GPS 40mm]',	161.15,	0,	'',	'https://m.media-amazon.com/images/I/61ZL5tN-+GL._AC_SL1500_.jpg',	'superadmin',	'WHY APPLE WATCH SE — All the essentials to help you be motivated and active, keep connected, track your health, and stay safe. The Smart Stack and redesigned apps in watchOS 10 help you see more information at a glance. With features like Crash Detection and enhanced workout metrics, Apple Watch SE is a better value than ever.\r\nCARBON NEUTRAL — Apple Watch SE (2nd generation) paired with the latest Sport Loop is carbon neutral. Learn more about Apple’s commitment to the environment at apple.com/2030.\r\nHEALTH AND SAFETY FEATURES — Get help when you need it with Fall Detection, Crash Detection, and Emergency SOS. Get deep insights into your health, including notifications if you have an irregular heart rhythm or an unusually high or low heart rate.\r\nSIMPLY COMPATIBLE — It works seamlessly with your Apple devices and services. Unlock your Mac automatically. Find your devices easily. Pay and send money with Apple Pay. Apple Watch requires iPhone XS or later with the latest iOS version.\r\nSWIMPROOF AND STYLISH — 50m water resistance. Three finishes. And a color-matched back case made with a production process that reduces its carbon emissions.\r\nEASILY CUSTOMIZABLE — With watch bands in a range of styles, materials, and colors and fully customizable watch faces, you can change your watch to fit your mood or the moment.\r\nA POWERFUL FITNESS PARTNER — The Workout app gives you a range of ways to train plus advanced metrics for more insights about your workout performance. And Apple Watch comes with three months of Apple Fitness+ free.\r\nSTAY CONNECTED — Send a text, take a call, listen to music and podcasts, use Siri, or call for help with Emergency SOS. Apple Watch SE (GPS) works with your iPhone or Wi-Fi to keep you connected.\r\nAPPLECARE — Every Apple Watch comes with one year of hardware repair coverage through its limited warranty and up to 90 days of complimentary technical support. Get AppleCare+ to extend your coverage and reduce the stress and cost of unexpected repairs.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See below to learn more.',	1,	0,	'Apple',	'Watch',	'Apple Watch SE'),
(5,	'Late 2020 Apple MacBook Air with Apple M1 Chip (13.3 inch, 8GB RAM, 256GB SSD)',	649.00,	0,	'',	'https://m.media-amazon.com/images/I/71fMZDz2sEL._AC_SL1500_.jpg',	'superadmin',	'Apple-designed M1 chip for a giant leap in CPU, GPU, and machine learning performance\r\nGo longer than ever with up to 18 hours of battery life\r\n8-core CPU delivers up to 3.5x faster performance to tackle projects faster than ever\r\nUp to eight GPU cores with up to 5x faster graphics for graphics-intensive apps and games\r\n16-core Neural Engine for advanced machine learning',	1,	1,	'Apple',	'Laptop',	'Macbook Air'),
(6,	'Apple iPad Air (5th Generation): with M1 chip, 10.9-inch Liquid Retina Display, 256GB, Wi-Fi 6, 12MP front/12MP Back Camera, Touch ID, All-Day Battery Life – Starlight',	639.00,	0,	'',	'https://m.media-amazon.com/images/I/61-3k7FKQRL._AC_SX679_.jpg',	'superadmin',	'WHY IPAD AIR — Serious performance in a thin and light design. With an immersive 10.9-inch Liquid Retina display and the amazing performance of the M1 chip, iPad Air is a creative and gaming powerhouse. Featuring Touch ID, advanced cameras, superfast Wi-Fi 6, and a USB-C connector.\r\nIPADOS + APPS — iPadOS makes iPad more productive, intuitive, and versatile. With iPadOS, run multiple apps at once, use Apple Pencil to write in any text field with Scribble, and edit and share photos. iPad Air comes with essential apps like Safari, Messages, and Keynote, with over a million more apps available on the App Store.\r\nFAST WI-FI CONNECTIVITY — Wi-Fi 6 gives you fast access to your files, uploads, and downloads, and lets you seamlessly stream your favorite shows.\r\nPERFORMANCE AND STORAGE — The M1 chip lets you multitask smoothly between powerful apps and play graphics-intensive games. And with all-day battery life, you can keep working and playing wherever you go. Choose from 64GB or 256GB storage options depending on the room you need for apps, music, movies, and more.\r\nAPPLE PENCIL AND MAGIC KEYBOARD — With Apple Pencil (2nd generation), iPad Air transforms into an immersive drawing canvas and the world’s best note‑taking device. Magic Keyboard features a great typing experience and a built‑in trackpad, while doubling as a protective cover for iPad. Accessories sold separately.\r\n10.9-INCH LIQUID RETINA DISPLAY — The gorgeous Liquid Retina display features advanced technologies like True Tone, P3 wide color, and ultralow reflectivity, which make everything look stunning.\r\nUNLOCK AND PAY WITH TOUCH ID — Touch ID is built into the top button, so you can use your fingerprint to unlock your iPad Air, sign in to apps, and make payments securely with Apple Pay.\r\nADVANCED CAMERAS — iPad Air features a 12MP Ultra Wide front camera that supports Center Stage for videoconferencing and selfies. The 12MP Wide back camera with True Tone flash is perfect for capturing photos and 4K videos.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features.',	1,	1,	'Apple',	'Ipad',	'iPad Air'),
(7,	'Apple iPad (10th Generation): with A14 Bionic chip, 10.9-inch Liquid Retina Display, 64GB, Wi-Fi 6, 12MP front/12MP Back Camera, Touch ID, All-Day Battery Life – Blue',	307.28,	0,	'',	'https://m.media-amazon.com/images/I/61uA2UVnYWL._AC_SX679_.jpg',	'superadmin',	'WHY IPAD — Colorfully reimagined and more versatile than ever, iPad is great for the things you do every day. With an all-screen design, 10.9-inch Liquid Retina display, powerful A14 Bionic chip, superfast Wi-Fi, and four gorgeous colors, iPad delivers a powerful way to create, stay connected, and get things done.\r\nIPADOS + APPS — iPadOS makes iPad more productive, intuitive, and versatile. With iPadOS, run multiple apps at once, use Apple Pencil to write in any text field with Scribble, and edit and share photos. iPad comes with essential apps like Safari, Messages, and Keynote, with over a million more apps available on the App Store.\r\nFAST WI-FI CONNECTIVITY — Wi-Fi 6 gives you fast access to your files, uploads, and downloads, and lets you seamlessly stream your favorite shows.\r\nPERFORMANCE AND STORAGE — The A14 Bionic chip delivers power and performance for any activity. And with all-day battery life, iPad is perfect for playing immersive games and editing photos and videos. Choose from 64GB or 256GB storage options.\r\nAPPLE PENCIL AND MAGIC KEYBOARD FOLIO — With Apple Pencil (1st generation), iPad transforms into an immersive drawing canvas and the world’s best note‑taking device. The Magic Keyboard Folio features a versatile two-piece design with a detachable keyboard and a protective back panel that both attach magnetically to iPad. Accessories sold separately.\r\n10.9-INCH LIQUID RETINA DISPLAY — The gorgeous Liquid Retina display is an amazing way to watch movies or draw your next masterpiece. True Tone adjusts the display to the color temperature of the room to make viewing comfortable in any light.\r\nUNLOCK AND PAY WITH TOUCH ID — Touch ID is built into the top button, so you can use your fingerprint to unlock your iPad, sign in to apps, and make payments securely with Apple Pay.\r\nADVANCED CAMERAS — iPad features a landscape 12MP Ultra Wide front camera that supports Center Stage for videoconferencing and selfies. Shoot 4K video or photos with the 12MP Wide back camera, then edit right on your iPad.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features.',	1,	1,	'Apple',	'Ipad',	'iPad'),
(8,	'Apple 2022 MacBook Air Laptop with M2 chip: 13.6-inch Liquid Retina Display, 8GB RAM, 256GB SSD Storage, Backlit Keyboard, 1080p FaceTime HD Camera. Works with iPhone and iPad; Midnight',	840.51,	0,	'',	'https://m.media-amazon.com/images/I/719C6bJv8jL._AC_SX679_.jpg',	'superadmin',	'STRIKINGLY THIN DESIGN — The redesigned MacBook Air is more portable than ever and weighs just 2.7 pounds. It’s the incredibly capable laptop that lets you work, play or create just about anything — anywhere.\r\nSUPERCHARGED BY M2 — Get more done faster with a next-generation 8-core CPU, up to 10-core GPU and up to 24GB of unified memory.\r\nUP TO 18 HOURS OF BATTERY LIFE — Go all day and into the night, thanks to the power-efficient performance of the Apple M2 chip.\r\nBIG, BEAUTIFUL DISPLAY — The 13.6-inch Liquid Retina display features over 500 nits of brightness, P3 wide color and support for 1 billion colors for vibrant images and incredible detail.\r\nADVANCED CAMERA AND AUDIO — Look sharp and sound great with a 1080p FaceTime HD camera, three-mic array and four-speaker sound system with Spatial Audio.\r\nVERSATILE CONNECTIVITY — MacBook Air features a MagSafe charging port, two Thunderbolt ports and a headphone jack.\r\nEASY TO USE — Your Mac feels familiar from the moment you turn it on, and works seamlessly with all your Apple devices.\r\nBUILT TO LAST — The all-aluminium unibody enclosure is exceptionally durable. And free software updates keep things running smooth and secure for years to come.\r\nSIMPLY COMPATIBLE — All your go-to apps run lightning-fast — including Microsoft 365, Zoom, and many of your favorite iPhone and iPad apps.\r\nCOMES WITH APPLECARE WARRANTY – Every Mac comes with a one-year limited warranty and up to 90 days of complimentary technical support. Get AppleCare plus to extend your coverage.',	1,	1,	'Apple',	'Laptop',	'MacBook Air'),
(9,	'Apple AirPods (3rd Generation) Wireless Ear Buds, Bluetooth Headphones, Personalized Spatial Audio, Sweat and Water Resistant, Lightning Charging Case Included, Up to 30 Hours of Battery Life',	505.00,	0,	'',	'https://m.media-amazon.com/images/I/61df2M5+OnL._AC_SX679_.jpg',	'superadmin',	'PERSONALIZED SPATIAL AUDIO — With sound that suits your unique ear shape along with dynamic head tracking, AirPods (3rd generation) deliver an immersive listening experience that places sound all around you. You can also listen to select songs, shows, and movies in Dolby Atmos.\r\nSWEAT AND WATER PROTECTION — AirPods and the Lightning Charging Case is rated IPX4 sweat and water resistant, so they’ll withstand anything from heavy workouts to rain.\r\nA POWERFUL CASE — Recharge your AirPods with the portable Lightning Charging Case for power throughout the day, wherever you go.\r\nPINCH-PERFECT CONTROL — The force sensor lets you control your entertainment as well as answer, end, and mute or unmute yourself on calls.\r\nLONG BATTERY LIFE — Up to 6 hours of listening time with one charge, and up to 30 hours total listening time with the Lightning Charging Case.\r\nALWAYS-ON “HEY SIRI” — Say “Hey Siri” to activate your favorite personal assistant and stay on top of everyday tasks like playing music, making calls, getting directions, or checking your schedule.\r\nMAGICAL EXPERIENCE — Place AirPods near your iPhone or iPad and tap Connect to pair with every device in your iCloud account. Audio seamlessly switches between devices and automatically pauses when you take AirPods out of your ears.\r\nAUDIO SHARING — Audio Sharing lets you connect two sets of AirPods effortlessly to your iPhone, iPad, iPod touch, or Apple TV, with individual volume control for each set.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See “Additional information” to learn more.',	1,	1,	'Apple',	'Headphones',	'AirPods'),
(10, 'Apple 2024 MacBook Air 13-inch Laptop with M3 chip: 13.6-inch Liquid Retina Display, 8GB Unified Memory, 256GB SSD Storage, Backlit Keyboard, 1080p FaceTime HD Camera, Touch ID; Starlight',	959.04,	0,	'',	'https://m.media-amazon.com/images/I/71YG+VrvrTL._AC_SX679_.jpg',	'superadmin',	'LEAN. MEAN. M3 MACHINE — The blazing-fast MacBook Air with the M3 chip is a superportable laptop that sails through work and play.\r\nPORTABLE DESIGN — Lightweight and under half an inch thin, so you can take MacBook Air anywhere you go.\r\nGET MORE DONE FASTER — The powerful 8-core CPU and up to 10-core GPU of the Apple M3 chip keep things running smoothly.\r\nUP TO 18 HOURS OF BATTERY LIFE — Amazing, all-day battery life so you can leave the power adapter at home.\r\nA BRILLIANT DISPLAY — The 13.6-inch Liquid Retina display supports 1 billion colors.\r\nLOOK SHARP, SOUND GREAT — Everything looks and sounds amazing with a 1080p FaceTime HD camera, three mics, and four speakers with Spatial Audio.\r\nAPPS FLY WITH APPLE SILICON — All your favorites, from Microsoft 365 to Adobe Creative Cloud, run lightning fast in macOS.\r\nGET CONNECTED — MacBook Air features two Thunderbolt ports, a headphone jack, Wi-Fi 6E, Bluetooth 5.3, and a MagSafe charging port. And connect up to two external displays with the laptop lid closed.\r\nIF YOU LOVE IPHONE, YOU’LL LOVE MAC — MacBook Air works like magic with your other Apple devices. Start an email on your iPhone and finish it on your Mac. Send text messages from your Mac. And much more.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See below to learn more.',	1,	1,	'Apple',	'Laptop',	'MacBook Air'),
(11, 'Apple AirPods Max Wireless Over-Ear Headphones, Active Noise Cancelling, Transparency Mode, Personalized Spatial Audio, Dolby Atmos, Bluetooth Headphones for iPhone – Space Gray',	445.49,	0,	'',	'https://m.media-amazon.com/images/I/81jqUPkIVRL._AC_SX679_.jpg',	'superadmin',	'BREATHTAKING AUDIO QUALITY — Apple-designed dynamic driver provides high-fidelity audio. Computational audio combines custom acoustic design with the Apple H1 chip and software for breakthrough listening experiences.\r\nFOCUS ON WHAT’S PLAYING — Active Noise Cancellation blocks outside noise so you can immerse yourself in music.\r\nHEAR THE WORLD AROUND YOU — Transparency mode lets you hear and interact with the world around you.\r\nPERSONALIZED SPATIAL AUDIO — With sound that suits your unique ear shape along with dynamic head tracking, AirPods Max deliver an immersive listening experience that places sound all around you. You can also listen to select songs, shows, and movies in Dolby Atmos.\r\nACOUSTIC-FIRST DESIGN — Designed with a knit-mesh canopy and memory foam ear cushions for an exceptional over-ear fit that perfectly seals in sound.\r\nMAGICAL EXPERIENCE — Pair AirPods Max by simply placing them near your device and tapping Connect on your screen. AirPods Max pause audio when you take them off. And Automatic Switching makes listening between your iPhone, iPad, and Mac completely effortless.\r\nLONG BATTERY LIFE — Up to 20 hours of listening, movie watching, or talk time with Active Noise Cancellation and Personalized Spatial Audio enabled.\r\nPRECISION CONTROL — Use the Digital Crown to play and pause music, to answer, end, and mute yourself on calls, and to control volume and skip between tracks.\r\nA SMARTER CASE — Store in an ultra low-power state with the slim Smart Case.\r\nLEGAL DISCLAIMERS — This is a summary of the main product features. See “Additional information” to learn more.',	1,	1,	'Apple',	'Headphones',	'AirPods Max'),
(12, 'ZAGG Pro Keys Wireless Keyboard & Detachable Case for iPad Pro 12.9 - Backlit Keys, Apple Pencil Holder, 6.6ft Drop Protection',	181.99,	0,	'',	'https://m.media-amazon.com/images/I/71llf8HQ5CL.__AC_SX300_SY300_QL70_FMwebp_.jpg',	'superadmin',	'Bluetooth Trackpad - Bluetooth-integrated trackpad is compatible with iPadOS and can be turned on and off.\r\nDetachable Keyboard and Case - The keyboard and case detach to accommodate different uses and environments.\r\nBacklit, Laptop-style Keys - Pro Keys have clean, precise keystrokes. Backlighting, in seven different colors, makes typing easy in low-light conditions.\r\nMulti-device Pairing - Connect with two devices simultaneously and toggle back and forth between them.\r\nThree-Month Battery - With the trackpad on, the keyboard can last up to 3 months on one charge. Turning the trackpad off preserves battery life.\r\nKeyboard Operating System: iOS',	1,	0,	'ZAGG',	'iPad',	NULL),
(13, 'Apple 2023 MacBook Pro Laptop M3 Max chip with 16‑core CPU, 40‑core GPU: 16.2-inch Liquid Retina XDR Display, 48GB Unified Memory, 1TB SSD Storage. Works with iPhone/iPad; Silver',	3421.48,	0,	'',	'https://m.media-amazon.com/images/I/61dnax4xchL._AC_SX679_.jpg',	'superadmin',	'SUPERCHARGED BY M3 PRO OR M3 MAX — The Apple M3 Pro chip, with a 12-core CPU and 18-core GPU, delivers amazing performance for demanding workflows like manipulating gigapixel panoramas or compiling millions of lines of code. M3 Max, with an up to 16-core CPU and up to 40-core GPU, drives extreme performance for the most advanced workflows like rendering intricate 3D content or developing transformer models with billions of parameters.\r\nUP TO 22 HOURS OF BATTERY LIFE — Go all day thanks to the power-efficient design of Apple silicon. The MacBook Pro laptop delivers the same exceptional performance whether it’s running on battery or plugged in. (Battery life varies by use and configuration. See apple.com/batteries for more information.)\r\nBRILLIANT PRO DISPLAY — The 16.2-inch Liquid Retina XDR display features Extreme Dynamic Range, over 1000 nits of brightness for stunning HDR content, up to 600 nits of brightness for SDR content, and pro reference modes for doing your best work on the go. (The display has rounded corners at the top. When measured diagonally, the screen is 16.2 inches. Actual viewable area is less.)\r\nFULLY COMPATIBLE — All your pro apps run lightning fast — including Adobe Creative Cloud, Apple Xcode, Microsoft 365, SideFX Houdini, MathWorks MATLAB, Medivis SurgicalAR, and many of your favorite iPhone and iPad apps. And with macOS, work and play on your Mac are even more powerful. Elevate your presence on video calls. Access information in all-new ways. And discover even more ways to personalize your Mac. (Apps are available on the App Store.)\r\nADVANCED CAMERA AND AUDIO — Look sharp and sound great with a 1080p FaceTime HD camera, a studio-quality three-mic array, and a six-speaker sound system with Spatial Audio.\r\nCONNECT IT ALL — This MacBook Pro features a MagSafe charging port, three Thunderbolt 4 ports, an SDXC card slot, an HDMI port, and a headphone jack. Enjoy fast wireless connectivity with Wi-Fi 6E and Bluetooth 5.3. And you can connect up to two external displays with M3 Pro, or up to four with M3 Max. (Wi‑Fi 6E available in countries and regions where supported.)\r\nMAGIC KEYBOARD WITH TOUCH ID — The backlit Magic Keyboard has a full-height function key row and Touch ID, which gives you a fast, easy, secure way to unlock your laptop and sign in to apps and sites.\r\nADVANCED SECURITY — Every Mac comes with encryption, robust virus protections, and a powerful firewall system. And free security updates help keep your Mac protected.\r\nWORKS WITH ALL YOUR APPLE DEVICES — You can do amazing things when you use your Apple devices together. Copy something on iPhone and paste it on MacBook Pro. Use your MacBook Pro to answer FaceTime calls or send texts with Messages. And that’s just the beginning.\r\nBUILT TO LAST — The all-aluminum unibody enclosure is exceptionally durable. Free software updates keep things running smoothly for years to come.',	1,	1,	'Apple',	'Laptop',	'MacBook Pro'),
